//
//  ReadingPlans.swift
//  BibleWish
//
//  Reading plans from biblewish.com (data generated by tools/build_plans.py), with progress kept
//  on the device. The on-track and streak math follows js/plans.js on the website.
//

import Foundation

struct PlanInfo: Codable, Identifiable, Hashable {
    let id: String
    let title: String
    let description: String
    let days: Int
    let chapters: Int
    let minutesPerDay: Int

    enum CodingKeys: String, CodingKey {
        case id, title, description, days, chapters
        case minutesPerDay = "minutes_per_day"
    }
}

/// One chapter of a plan day, by canonical book index and chapter number.
struct PlanChapter: Hashable {
    let book: Int
    let chapter: Int
}

struct PlanProgressEntry: Codable, Hashable {
    let day: Int
    let item: Int
    let completedAt: Date
}

struct UserPlan: Codable, Identifiable, Equatable {
    /// The plan id.
    let id: String
    /// Local calendar day the plan was started, "yyyy-MM-dd".
    let startedOn: String
    var progress: [PlanProgressEntry]
}

enum PlanStatus: Equatable {
    case onTrack
    case ahead(days: Int)
    case behind(days: Int)
    case complete

    var text: String {
        switch self {
        case .onTrack: return "On track"
        case .ahead(let days): return "\(days) day\(days == 1 ? "" : "s") ahead"
        case .behind(let days): return "\(days) day\(days == 1 ? "" : "s") behind"
        case .complete: return "Completed"
        }
    }
}

struct PlanSummary {
    let days: [[PlanChapter]]
    let done: Set<String>
    let totalChapters: Int
    let completedDays: Int
    let nextDay: Int?
    let expectedDay: Int
    let status: PlanStatus
    let streak: Int

    var doneChapters: Int { done.count }

    var fraction: Double {
        totalChapters == 0 ? 0 : Double(done.count) / Double(totalChapters)
    }

    /// "<1%" instead of a discouraging "0%" once reading has started.
    var percentLabel: String {
        if done.count > 0 && fraction < 0.01 { return "<1%" }
        return "\(Int(fraction * 100))%"
    }

    func isItemDone(day: Int, item: Int) -> Bool {
        done.contains("\(day):\(item)")
    }

    func isDayDone(_ day: Int) -> Bool {
        days[day - 1].indices.allSatisfy { isItemDone(day: day, item: $0) }
    }
}

final class PlansStore: ObservableObject {

    let catalog: [PlanInfo]
    private let planDays: [String: [[PlanChapter]]]

    @Published private(set) var userPlans: [UserPlan] {
        didSet { save() }
    }

    /// Set by the sync engine to hear about changes made by the reader (not ones applied from the server).
    var onChange: ((SyncOp) -> Void)?

    private let storageKey = "reading_plans_v1"

    init() {
        var catalog: [PlanInfo] = []
        var planDays: [String: [[PlanChapter]]] = [:]

        struct BundledPlans: Decodable {
            let plans: [PlanInfo]
            let days: [String: [[[Int]]]]
        }

        if let url = Bundle.main.url(forResource: "reading_plans", withExtension: "json"),
           let data = try? Data(contentsOf: url),
           let decoded = try? JSONDecoder().decode(BundledPlans.self, from: data) {
            catalog = decoded.plans
            planDays = decoded.days.mapValues { days in
                days.map { items in
                    items.compactMap { $0.count == 2 ? PlanChapter(book: $0[0], chapter: $0[1]) : nil }
                }
            }
        } else {
            assertionFailure("reading_plans.json is missing or unreadable")
        }

        self.catalog = catalog
        self.planDays = planDays

        if let data = UserDefaults.standard.data(forKey: storageKey),
           let decoded = try? JSONDecoder().decode([UserPlan].self, from: data) {
            userPlans = decoded
        } else {
            userPlans = []
        }
    }

    // MARK: - Lookup

    func info(_ id: String) -> PlanInfo? {
        catalog.first { $0.id == id }
    }

    func days(for id: String) -> [[PlanChapter]] {
        planDays[id] ?? []
    }

    func userPlan(_ id: String) -> UserPlan? {
        userPlans.first { $0.id == id }
    }

    // MARK: - Changes

    func start(_ id: String, on date: Date = Date()) {
        guard info(id) != nil, userPlan(id) == nil else { return }
        userPlans.append(UserPlan(id: id, startedOn: Self.isoDay(date), progress: []))
        onChange?(.startPlan(id))
    }

    func stop(_ id: String) {
        guard userPlan(id) != nil else { return }
        userPlans.removeAll { $0.id == id }
        onChange?(.deletePlan(id))
    }

    func toggle(planId: String, day: Int, item: Int, at date: Date = Date()) {
        guard let index = userPlans.firstIndex(where: { $0.id == planId }) else { return }
        var plan = userPlans[index]

        if let existing = plan.progress.firstIndex(where: { $0.day == day && $0.item == item }) {
            plan.progress.remove(at: existing)
        } else {
            plan.progress.append(PlanProgressEntry(day: day, item: item, completedAt: date))
        }
        userPlans[index] = plan
        onChange?(.checkPlanItem(planId: planId, day: day, item: item))
    }

    // MARK: - Sync (these never call onChange)

    /// Whether a chapter of a plan is ticked (what the server should be told).
    func isTicked(planId: String, day: Int, item: Int) -> Bool {
        userPlan(planId)?.progress.contains { $0.day == day && $0.item == item } ?? false
    }

    /// Makes the plans match the server's. Plans this app doesn't know are left alone.
    func apply(serverPlans: [UserPlan]) {
        let known = serverPlans.filter { info($0.id) != nil }
        let sorted = known.sorted { $0.id < $1.id }
        let current = userPlans.sorted { $0.id < $1.id }
        if sorted != current {
            userPlans = known
        }
    }

    func removeAllLocal() {
        guard !userPlans.isEmpty else { return }
        userPlans = []
    }

    // MARK: - Progress

    func summary(for id: String, today: Date = Date()) -> PlanSummary? {
        guard let plan = userPlan(id) else { return nil }
        let days = self.days(for: id)
        guard !days.isEmpty else { return nil }

        let done = Set(plan.progress.map { "\($0.day):\($0.item)" })
        let totalChapters = days.reduce(0) { $0 + $1.count }

        var completedDays = 0
        var nextDay: Int?
        for day in 1...days.count {
            let complete = days[day - 1].indices.allSatisfy { done.contains("\(day):\($0)") }
            if complete {
                completedDays += 1
            } else if nextDay == nil {
                nextDay = day
            }
        }

        let elapsed = Self.daysBetween(plan.startedOn, and: Self.isoDay(today))
        let expectedDay = min(days.count, max(1, elapsed + 1))

        let status: PlanStatus
        if let next = nextDay {
            if next < expectedDay {
                status = .behind(days: expectedDay - next)
            } else if next > expectedDay {
                status = .ahead(days: next - expectedDay)
            } else {
                status = .onTrack
            }
        } else {
            status = .complete
        }

        return PlanSummary(
            days: days,
            done: done,
            totalChapters: totalChapters,
            completedDays: completedDays,
            nextDay: nextDay,
            expectedDay: expectedDay,
            status: status,
            streak: Self.streak(of: plan.progress.map(\.completedAt), today: today)
        )
    }

    /// Consecutive local days with at least one chapter read, ending today or yesterday.
    static func streak(of dates: [Date], today: Date) -> Int {
        let days = Set(dates.map(isoDay))
        var cursor = days.contains(isoDay(today)) ? today : addDays(-1, to: today)
        var streak = 0
        while days.contains(isoDay(cursor)) {
            streak += 1
            cursor = addDays(-1, to: cursor)
        }
        return streak
    }

    // MARK: - Labels

    /// [[0,34],[0,35],[0,36]] → "Genesis 34–36"; [[38,4],[39,1]] → "Malachi 4 · Matthew 1".
    static func label(forDay items: [PlanChapter], bookNames: [String]) -> String {
        var parts: [String] = []
        var start = 0

        while start < items.count {
            var end = start
            while end + 1 < items.count,
                  items[end + 1].book == items[start].book,
                  items[end + 1].chapter == items[end].chapter + 1 {
                end += 1
            }
            let name = items[start].book < bookNames.count ? bookNames[items[start].book] : "Book \(items[start].book + 1)"
            parts.append(end > start
                ? "\(name) \(items[start].chapter)\u{2013}\(items[end].chapter)"
                : "\(name) \(items[start].chapter)")
            start = end + 1
        }
        return parts.joined(separator: " \u{00B7} ")
    }

    // MARK: - Dates

    private static let isoFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.timeZone = .current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter
    }()

    static func isoDay(_ date: Date) -> String {
        isoFormatter.string(from: date)
    }

    private static func addDays(_ days: Int, to date: Date) -> Date {
        Calendar.current.date(byAdding: .day, value: days, to: date) ?? date
    }

    private static func daysBetween(_ first: String, and second: String) -> Int {
        guard let a = isoFormatter.date(from: first), let b = isoFormatter.date(from: second) else { return 0 }
        let calendar = Calendar.current
        return calendar.dateComponents([.day], from: calendar.startOfDay(for: a), to: calendar.startOfDay(for: b)).day ?? 0
    }

    // MARK: - Persistence

    private func save() {
        if let data = try? JSONEncoder().encode(userPlans) {
            UserDefaults.standard.set(data, forKey: storageKey)
        }
    }
}
